const fs = require('fs');
const content = fs.readFileSync('expo/lib/ivx-module-registry.ts', 'utf8');

// Extract all mod() calls with their sourceFiles
const modRegex = /mod\((\d+),\s*'([^']+)',/g;
const sourceRegex = /sourceFiles:\s*'([^']+)'/g;

let match;
let total = 0;
let verified = 0;
let missing = [];
let noSource = [];

// Get all lines that have mod() calls
const lines = content.split('\n');
for (const line of lines) {
  const modMatch = line.match(/mod\((\d+),\s*'([^']+)'/);
  if (!modMatch) continue;

  total++;
  const num = modMatch[1];
  const name = modMatch[2];

  const srcMatch = line.match(/sourceFiles:\s*'([^']+)'/);
  if (!srcMatch) {
    noSource.push({ num, name });
    continue;
  }

  const files = srcMatch[1].split(',').map(f => f.trim());
  let allExist = true;
  let missingFiles = [];

  for (const f of files) {
    // Skip directory references ending with /
    if (f.endsWith('/')) {
      if (!fs.existsSync(f)) {
        allExist = false;
        missingFiles.push(f);
      }
      continue;
    }
    if (!fs.existsSync(f)) {
      allExist = false;
      missingFiles.push(f);
    }
  }

  if (allExist) {
    verified++;
  } else {
    missing.push({ num, name, missingFiles });
  }
}

console.log('TOTAL MODULES:', total);
console.log('VERIFIED (all sourceFiles exist):', verified);
console.log('NO SOURCE FILES:', noSource.length);
if (noSource.length > 0) {
  noSource.forEach(m => console.log('  NO-SOURCE:', m.num, m.name));
}
console.log('MISSING FILES:', missing.length);
if (missing.length > 0) {
  missing.forEach(m => console.log('  MISSING:', m.num, m.name, '->', m.missingFiles.join(', ')));
}
"

